/**
 * Update DB with a new resource object, including job status, metadata and applicationId. Using
 * the submissionId hashset to reduce unnecessary updates.
 *
 * @param sparkCluster Spark cluster
 * @param prevCRDState the old resource object
 * @param currCRDState the new resource object
 */
private void onUpdateImpl_logApplication(AppConfig.SparkCluster sparkCluster, SparkApplication prevCRDState, SparkApplication currCRDState) {
    String submissionId = currCRDState.getMetadata().getName();
    String newState = SparkApplicationResourceHelper.getState(currCRDState);
    String oldState = SparkApplicationResourceHelper.getState(prevCRDState);
    int driverCore = 0;
    int driverMemoryMb = 0;
    int executorInstances = 0;
    int executorCore = 0;
    int executorMemoryMb = 0;
    String dagName = "";
    String taskName = "";
    String appName = "";
    if (newState != null && !newState.equals(oldState)) {
        logger.info("Got event for submission {}, state changed: {} -> {}", submissionId, oldState, newState);
        logDao.logApplicationStatus(submissionId, newState);
        Timestamp startTime = null;
        if (!driverInfoCollectedSubIds.contains(submissionId) && newState.equals(SparkConstants.RUNNING_STATE)) {
            try (KubernetesClient client = KubernetesHelper.getK8sClient(sparkCluster)) {
                String driverStartTime;
                SparkApplicationSpec spec = currCRDState.getSpec();
                DriverSpec driverSpec = null;
                ExecutorSpec executorSpec = null;
                Map<String, String> driverSparkConf = null;
                Map<String, String> driverSparkConfLabels = null;
                if (spec != null) {
                    driverSpec = spec.getDriver();
                    executorSpec = spec.getExecutor();
                    driverSparkConf = spec.getSparkConf();
                    if (driverSpec != null) {
                        driverSparkConfLabels = driverSpec.getLabels();
                        if (driverSparkConfLabels != null) {
                            dagName = driverSparkConfLabels.get("dag_name");
                            taskName = driverSparkConfLabels.get("task_name");
                        }
                    }
                    if (driverSparkConf != null) {
                        appName = currCRDState.getSpec().getSparkConf().get(SparkConstants.SPARK_APP_NAME_LABEL);
                    }
                    if (executorSpec != null) {
                        executorInstances = executorSpec.getInstances();
                    }
                }
                Pod driver_pod;
                try {
                    driver_pod = client.pods().inNamespace(sparkCluster.getSparkApplicationNamespace()).withName(submissionId + "-driver").get();
                    if (driver_pod != null) {
                        try {
                            driverStartTime = driver_pod.getStatus().getStartTime();
                            driverCore = Integer.parseInt(driver_pod.getSpec().getContainers().get(0).getResources().getRequests().get("cpu").getAmount());
                            driverMemoryMb = Integer.valueOf(driver_pod.getSpec().getContainers().get(0).getResources().getRequests().get("memory").getAmount());
                            if (StringUtils.isNotEmpty(driverStartTime) && driverCore != 0 && driverMemoryMb != 0 && executorInstances != 0) {
                                startTime = new Timestamp(DateTimeUtils.parseOrNull(driverStartTime));
                                // only add the submission_id into the hashset when the info is successfully
                                // updated into database
                                if (logDao.updateJobInfo(submissionId, startTime, driverCore, driverMemoryMb, executorInstances, dagName, taskName, appName)) {
                                    driverInfoCollectedSubIds.add(submissionId);
                                }
                            }
                        } catch (Exception e) {
                            logger.warn(String.format("Failed to get driver info from driver pod for submissionId %s", submissionId), e);
                        }
                    }
                } catch (Exception e) {
                    logger.warn(String.format("Failed to get driver pod for submissionId %s", submissionId), e);
                }
            } catch (Exception e) {
                logger.warn(String.format("Failed to update driver info for submissionId %s", submissionId), e);
            }
        }
        if (currCRDState.getStatus() != null && currCRDState.getStatus().getSparkApplicationId() != null) {
            String appId = currCRDState.getStatus().getSparkApplicationId();
            logger.info("Got event for submission {}, application id: {}", submissionId, appId);
            logDao.logApplicationId(submissionId, appId);
        }
        if (SparkConstants.isApplicationStopped(newState)) {
            Timestamp finishedTime = null;
            if (currCRDState.getStatus() != null && currCRDState.getStatus().getTerminationTime() != null) {
                Long millis = DateTimeUtils.parseOrNull(currCRDState.getStatus().getTerminationTime());
                finishedTime = new Timestamp(millis);
            }
            logDao.logApplicationFinished(submissionId, newState, finishedTime, appConfig.getvCoreSecondCost(), appConfig.getMemoryMbSecondCost());
            driverInfoCollectedSubIds.remove(submissionId);
            String user = currCRDState.getMetadata().getLabels().get(Constants.PROXY_USER_LABEL);
            if (user == null) {
                user = "";
            }
            String sparkVersion = currCRDState.getSpec().getSparkVersion();
            if (sparkVersion == null) {
                sparkVersion = "";
            }
            requestCounters.increment(APPLICATION_FINISH_METRIC_NAME, Tag.of("status", newState), Tag.of("user", user), Tag.of("spark_version", sparkVersion), Tag.of("spark_cluster", ApplicationSubmissionHelper.getClusterIdFromSubmissionId(submissionId)));
        }
    }
}
